import{_ as s,o as i,c as e,a2 as n}from"./chunks/framework.Lq8Lraw_.js";const k=JSON.parse('{"title":"06 分支合并与快进","description":"","frontmatter":{},"headers":[],"relativePath":"guide/intermediate/01-branch-merge.md","filePath":"guide/intermediate/01-branch-merge.md","lastUpdated":1792671989000}'),t={name:"guide/intermediate/01-branch-merge.md"};function p(l,a,h,d,c,r){return i(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="_06-分支合并与快进" tabindex="-1">06 分支合并与快进 <a class="header-anchor" href="#_06-分支合并与快进" aria-label="Permalink to &quot;06 分支合并与快进&quot;">​</a></h1><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>能判断一次合并会走快进（fast-forward）还是三方合并（three-way merge）。</li><li>能用 ASCII 图画出两种合并后的提交图差异。</li><li>能使用 <code>git merge</code>、<code>git merge --no-ff</code> 并按团队策略选择合并方式。</li><li>能解释合并提交为什么有两个父提交，并用 <code>git cat-file -p</code> 验证。</li><li>能在合并完成后安全删除分支，并用 <code>git log --graph</code> 检查结果。</li></ul><h2 id="合并的两种形态" tabindex="-1">合并的两种形态 <a class="header-anchor" href="#合并的两种形态" aria-label="Permalink to &quot;合并的两种形态&quot;">​</a></h2><p><code>git merge &lt;branch&gt;</code> 把指定分支的变更并入当前分支。设当前在 <code>main</code>，要合并 <code>feature/login</code>，结果取决于两条分支是否已经分叉：</p><table tabindex="0"><thead><tr><th>条件</th><th>合并方式</th><th>是否产生合并提交</th></tr></thead><tbody><tr><td><code>main</code> 是 <code>feature</code> 的祖先（feature 只是领先）</td><td>快进（fast-forward）</td><td>否，只移动指针</td></tr><tr><td>两条分支各自有新提交</td><td>三方合并（three-way merge）</td><td>是，两个父提交</td></tr></tbody></table><p>判断是否分叉：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --graph</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --decorate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># * 4c5d6e7 (feature/login) feat: 登录页面</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># * 3b4c5d6 feat: 登录接口</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># * 2a9c7f1 (HEAD -&gt; main) chore: 初始化项目</span></span></code></pre></div><p>此时 <code>main</code> 停在 <code>2a9c7f1</code>，没有新提交，合并会快进。</p><h2 id="快进合并" tabindex="-1">快进合并 <a class="header-anchor" href="#快进合并" aria-label="Permalink to &quot;快进合并&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/login</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Updating 2a9c7f1..4c5d6e7</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Fast-forward</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#  src/login.ts | 42 ++++++++++++++++++++++++++++++++++++++++++++</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#  1 file changed, 42 insertions(+)</span></span></code></pre></div><p>合并前后：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>合并前：</span></span>
<span class="line"><span>* 4c5d6e7 feat: 登录页面      ← feature/login</span></span>
<span class="line"><span>* 3b4c5d6 feat: 登录接口</span></span>
<span class="line"><span>* 2a9c7f1 chore: 初始化项目    ← HEAD -&gt; main</span></span>
<span class="line"><span></span></span>
<span class="line"><span>合并后：</span></span>
<span class="line"><span>* 4c5d6e7 feat: 登录页面      ← HEAD -&gt; main, feature/login</span></span>
<span class="line"><span>* 3b4c5d6 feat: 登录接口</span></span>
<span class="line"><span>* 2a9c7f1 chore: 初始化项目</span></span></code></pre></div><p>快进的本质是把 <code>main</code> 指针直接移到 <code>feature</code> 的位置，不创建新对象。历史保持一条直线，看起来像所有提交都直接发生在 <code>main</code> 上。</p><p>快进的优点是不产生额外提交；缺点是丢失了「这些提交属于同一个功能分支」的信息，事后无法从图上看出功能边界。</p><h2 id="三方合并" tabindex="-1">三方合并 <a class="header-anchor" href="#三方合并" aria-label="Permalink to &quot;三方合并&quot;">​</a></h2><p>两条分支从共同祖先分叉后各自前进：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>* 8b1e0d4 fix: 修复超时          ← HEAD -&gt; main</span></span>
<span class="line"><span>| * 4c5d6e7 feat: 登录页面       ← feature/login</span></span>
<span class="line"><span>| * 3b4c5d6 feat: 登录接口</span></span>
<span class="line"><span>|/</span></span>
<span class="line"><span>* 2a9c7f1 chore: 初始化项目      ← 共同祖先（merge base）</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/login</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Merge made by the &#39;ort&#39; strategy.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#  src/login.ts | 42 ++++++++++++++++++++++++++++++++++++++++++++</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#  1 file created</span></span></code></pre></div><p>结果：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*   9a8b7c6 (HEAD -&gt; main) Merge branch &#39;feature/login&#39;</span></span>
<span class="line"><span>|\\</span></span>
<span class="line"><span>| * 4c5d6e7 (feature/login) feat: 登录页面</span></span>
<span class="line"><span>| * 3b4c5d6 feat: 登录接口</span></span>
<span class="line"><span>* | 8b1e0d4 fix: 修复超时</span></span>
<span class="line"><span>|/</span></span>
<span class="line"><span>* 2a9c7f1 chore: 初始化项目</span></span></code></pre></div><p>Git 使用三方合并算法：取共同祖先 <code>2a9c7f1</code> 作为基准（base），分别比较 <code>main</code> 的 <code>8b1e0d4</code> 和 <code>feature</code> 的 <code>4c5d6e7</code>。只有一方修改的区域直接采纳，双方都修改同一区域时产生冲突。</p><p>合并提交 <code>9a8b7c6</code> 同时记录两个父提交，把两条历史线连接起来。</p><h2 id="验证合并提交" tabindex="-1">验证合并提交 <a class="header-anchor" href="#验证合并提交" aria-label="Permalink to &quot;验证合并提交&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --graph</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --decorate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -5</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># *   9a8b7c6 (HEAD -&gt; main) Merge branch &#39;feature/login&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># |\\</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># | * 4c5d6e7 (feature/login) feat: 登录页面</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># | * 3b4c5d6 feat: 登录接口</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># * | 8b1e0d4 fix: 修复超时</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># |/</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># * 2a9c7f1 chore: 初始化项目</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat-file</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HEAD</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># tree 5d6e7f8...</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># parent 8b1e0d4a1b2c3d4e5f60718293a4b5c6d7e8f901</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># parent 4c5d6e7b2c3d4e5f60718293a4b5c6d7e8f9012a</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># author Zhang San &lt;zhangsan@example.com&gt; 1760000000 +0800</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># committer Zhang San &lt;zhangsan@example.com&gt; 1760000000 +0800</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Merge branch &#39;feature/login&#39;</span></span></code></pre></div><p>普通提交只有一个 <code>parent</code> 行，合并提交有两个。<code>git show HEAD</code> 默认展示合并提交相对第一父提交的差异，也就是 <code>feature</code> 分支带来的全部改动。</p><h2 id="git-merge-no-ff" tabindex="-1">git merge --no-ff <a class="header-anchor" href="#git-merge-no-ff" aria-label="Permalink to &quot;git merge --no-ff&quot;">​</a></h2><p>即使可以快进，也强制生成合并提交：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-ff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;merge: 合并登录功能&quot;</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>快进（ff）：</span></span>
<span class="line"><span>* 4c5d6e7 (HEAD -&gt; main, feature/login) feat: 登录页面</span></span>
<span class="line"><span>* 3b4c5d6 feat: 登录接口</span></span>
<span class="line"><span>* 2a9c7f1 chore: 初始化项目</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止快进（no-ff）：</span></span>
<span class="line"><span>*   9a8b7c6 (HEAD -&gt; main) merge: 合并登录功能</span></span>
<span class="line"><span>|\\</span></span>
<span class="line"><span>| * 4c5d6e7 (feature/login) feat: 登录页面</span></span>
<span class="line"><span>| * 3b4c5d6 feat: 登录接口</span></span>
<span class="line"><span>|/</span></span>
<span class="line"><span>* 2a9c7f1 chore: 初始化项目</span></span></code></pre></div><p>选择依据：</p><table tabindex="0"><thead><tr><th>场景</th><th>建议</th><th>原因</th></tr></thead><tbody><tr><td>个人分支、提交已整理成线性</td><td>允许快进</td><td>历史干净，无多余提交</td></tr><tr><td>功能分支需要保留边界</td><td><code>--no-ff</code></td><td>图上能看出整个功能是一个合并单元</td></tr><tr><td>发布分支合入主干</td><td><code>--no-ff</code></td><td>便于按功能整体回滚</td></tr><tr><td>平台开启「Create a merge commit」</td><td>走 no-ff</td><td>与 PR 记录对应</td></tr></tbody></table><p><code>--no-ff</code> 的代价是多一个提交；收益是合并单元明确，<code>git revert -m 1 &lt;merge-commit&gt;</code> 可以一次撤销整个功能。</p><h2 id="合并后的清理" tabindex="-1">合并后的清理 <a class="header-anchor" href="#合并后的清理" aria-label="Permalink to &quot;合并后的清理&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/login</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Deleted branch feature/login (was 4c5d6e7).</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># * main</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   remotes/origin/main</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   remotes/origin/feature/login</span></span></code></pre></div><p>本地分支删除后，远程跟踪分支仍可能存在。远程分支的删除与多人协作流程见 <a href="/git-tutorial-site/guide/collaboration/01-remote-workflow">11 远程协作全流程</a>。</p><h2 id="合并冲突" tabindex="-1">合并冲突 <a class="header-anchor" href="#合并冲突" aria-label="Permalink to &quot;合并冲突&quot;">​</a></h2><p>两边修改同一区域时合并会暂停，<code>git status -s</code> 显示 <code>UU</code>。解决冲突文件后 <code>git add</code> 并用 <code>git commit</code> 完成合并；放弃本次合并用 <code>git merge --abort</code>。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">合并方向搞反</p><p>在 <code>feature/login</code> 上执行 <code>git merge main</code>，会把主干变更并入功能分支；真正想做的通常是切到 <code>main</code> 再合并功能分支。方向反了不会立刻报错，但会产生大量无意义的合并提交。合并前先 <code>git branch --show-current</code> 确认位置。</p></div><div class="warning custom-block"><p class="custom-block-title">快进合并后无法用单个 revert 撤销整个功能</p><p>快进不会留下合并提交，功能中的每个提交都直接落在 <code>main</code> 上。要整体撤销只能逐个 revert，或 reset 到合并前（会改写历史）。需要「一个功能一个可回滚单元」时使用 <code>--no-ff</code>。参见 <a href="/git-tutorial-site/guide/intermediate/03-revert">08 revert</a>。</p></div><div class="tip custom-block"><p class="custom-block-title">合并前保证工作区干净</p><p>有未提交改动时，Git 可能拒绝合并，或在可自动合并的情况下把改动带入结果。先 <code>git status -s</code>，必要时 <code>git stash</code> 暂存现场（见 <a href="/git-tutorial-site/guide/intermediate/04-stash">09 stash</a>）。</p></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>目标分支未分叉时快进，只移动指针；分叉时三方合并，产生两个父提交的合并提交。</li><li>三方合并以共同祖先为基准，比较两个分支的最新提交。</li><li><code>--no-ff</code> 强制保留合并提交，适合需要明确功能边界的团队策略。</li><li>合并提交是「一个功能一个单元」的抓手，也是整体回滚的入口。</li><li>合并后先看图确认结构，再删除已合入的分支。</li></ul><p>合并让历史出现分叉与汇合，下一章处理另一种常见需求：改错了如何撤销，见 <a href="/git-tutorial-site/guide/intermediate/02-undo-restore-reset">07 撤销的艺术</a>。</p>`,45)])])}const g=s(t,[["render",p]]);export{k as __pageData,g as default};
